import type { SqlPredicate } from './commands.ts';
import { textKeyEncoder } from '../shared/collation/encoder.ts';
import type { CursorPayload } from '../shared/cursor.ts';
import { ApiFailure } from '../shared/errors.ts';
// Persisted entity IDs are canonical lowercase UUIDs generated by the server or
// the locked source map. ICU compares their primary order like ASCII. A forged
// uppercase cursor still retains the original ICU tertiary equality behavior.
export function localeIdSeek(
  idExpression: string,
  id: string,
  direction: 'asc' | 'desc',
): SqlPredicate {
  const lower = id.toLowerCase(),
    comparison = direction === 'asc' ? '>' : id === lower ? '<' : '<=';
  return { sql: `${idExpression}${comparison}?`, parameters: [lower] };
}
export function localeTupleSeek(
  keyExpression: string,
  idExpression: string,
  cursor: CursorPayload,
  direction: 'asc' | 'desc',
  idDirection: 'asc' | 'desc' = 'asc',
  kind: 'text' | 'numeric' = 'text',
): SqlPredicate {
  if (
    cursor.sortValue === null ||
    (kind === 'text' && typeof cursor.sortValue !== 'string') ||
    (kind === 'numeric' && typeof cursor.sortValue !== 'number')
  )
    throw new ApiFailure('VALIDATION_ERROR', 'Invalid cursor for query');
  const key = kind === 'text' ? textKeyEncoder.locale(String(cursor.sortValue)) : cursor.sortValue;
  const tie = localeIdSeek(idExpression, cursor.id, idDirection);
  return {
    sql: `(${keyExpression}${direction === 'desc' ? '<' : '>'}? OR (${keyExpression}=? AND ${tie.sql}))`,
    parameters: [key, key, ...tie.parameters],
  };
}
